function solve({config,state,event}){
  let a=Array.isArray(state)?state:[];
  const key=event.key, type=event.type;
  let i=a.findIndex(x=>x.key===key), status="ignored", value=null;
  if(type==="put"){
    if(i>=0){
      if(!a[i].tomb){a[i].value=event.value;status="stored"}
      else status="blocked";
    }else{
      if(a.length>=config.capacity){let j=a.findIndex(x=>x.pins===0);if(j<0)status="blocked";else{a.splice(j,1);a.push({key:key,value:event.value,pins:0,tomb:false});status="stored"}}
      else{a.push({key:key,value:event.value,pins:0,tomb:false});status="stored"}
    }
  }else if(type==="pin"){
    if(i<0)status="missing";else if(a[i].tomb)status="ignored";else{a[i].pins++;status="pinned"}
  }else if(type==="unpin"){
    if(i<0||a[i].pins===0)status="ignored";else{a[i].pins--;status="released";if(a[i].tomb&&a[i].pins===0){a.splice(i,1)}}
  }else if(type==="invalidate"){
    if(i<0)status="missing";else if(a[i].tomb)status="ignored";else if(a[i].pins>0){a[i].tomb=true;status="invalidated"}else{a.splice(i,1);status="invalidated"}
  }else if(type==="get"){
    if(i>=0&&!a[i].tomb){value=a[i].value;status="hit"}else status="miss";
  }
  const order=a.map(x=>x.key),pins={},t=[];
  for(const x of a){pins[x.key]=x.pins;if(x.tomb)t.push(x.key)}
  t.sort();
  return {state:a,output:{status:status,value:value,order:order,pins:pins,tombstones:t}};
}
